import { useEffect, useState } from "react";
import { INDEX_URL } from "../constants";
import type { ImageCategory, ImageIndex, ImageProject } from "../types";

type IndexState =
  | { status: "loading" }
  | { status: "error"; error: string }
  | { status: "ready"; projects: ImageProject[]; categories: ImageCategory[] };

/** Load the project catalogue generated by `npm run image:index`. */
export function useImageIndex(): IndexState {
  const [state, setState] = useState<IndexState>({ status: "loading" });

  useEffect(() => {
    let cancelled = false;
    fetch(INDEX_URL, { cache: "no-cache" })
      .then(async (res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = (await res.json()) as ImageIndex;
        if (!cancelled) setState({ status: "ready", projects: data.projects, categories: data.categories ?? [] });
      })
      .catch((err) => {
        if (!cancelled) setState({ status: "error", error: err instanceof Error ? err.message : String(err) });
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}
